/**
 * Full & Final Settlement domain — computes separation payments with tax
 * exemptions (Sec 10(10), 10(10AA), 10(10B), 10(10C)) and TDS true-up.
 *
 * Pure function. Receives all inputs, returns the full breakdown. No DB access.
 * All monetary values in paise (bigint).
 */

import {
  computeGratuityExemption,
  computeLeaveEncashExemption,
  computeRetrenchmentExemption,
  computeVrsExemption,
  type SeparationType,
  type EmployeeCategory,
  type GratuityExemptionResult,
  type LeaveEncashExemptionResult,
  type RetrenchmentExemptionResult,
  type VrsExemptionResult,
} from "../tax/exemptions.js";
import { computeTax, stdDeduction, type Regime } from "../tax/engine.js";

export interface FnfInput {
  employeeId: string;
  tenantId: string;
  separationType: SeparationType;
  separationDate: string;
  employeeCategory: EmployeeCategory;
  // Gross F&F amounts (from hrms-service fnf-calculate)
  noticeBuyoutMinor: bigint;
  leaveEncashmentGrossMinor: bigint;
  gratuityGrossMinor: bigint;
  retrenchmentCompMinor: bigint;
  vrsCompMinor: bigint;
  arrearsMinor: bigint;
  // Inputs for exemption computation
  lastDrawnWagesMinor: bigint;      // monthly basic + DA
  completedYears: number;            // 6-month rounding per PG Act
  avgSalaryLast10MonthsMinor: bigint;
  leaveBalanceDays: number;
  priorLeaveEncashExemptionMinor: bigint;
  // VRS-specific
  remainingMonthsToRetirement: number;
  // Tax context for the FY of separation
  taxRegime: Regime;
  salaryYtdMinor: bigint;          // total salary already paid this FY
  tdsYtdMinor: bigint;             // total TDS already deducted this FY
  deductions80cMinor: bigint;       // Ch VI-A deductions declared
  deductions80dMinor: bigint;
  otherDeductionsMinor: bigint;
  fyStartYear: number;
  // Exemption ceilings (loaded from DB)
  gratuityCeilingMinor: bigint;
  leaveEncashCeilingMinor: bigint;
  retrenchmentCeilingMinor: bigint;
  vrsCeilingMinor: bigint;
}

export interface FnfResult {
  gratuityExemption: GratuityExemptionResult;
  leaveEncashExemption: LeaveEncashExemptionResult;
  retrenchmentExemption: RetrenchmentExemptionResult | null;
  vrsExemption: VrsExemptionResult | null;
  // Aggregates
  totalGrossMinor: bigint;
  totalExemptMinor: bigint;
  totalTaxableOnSeparationMinor: bigint;
  // FY-level tax
  annualTaxableMinor: bigint;
  annualTaxMinor: bigint;
  tdsAlreadyDeductedMinor: bigint;
  tdsOnSeparationMinor: bigint;
  netPayableMinor: bigint;
}

/**
 * Compute a full F&F settlement with tax exemptions and TDS true-up.
 *
 * Flow:
 * 1. Compute exemptions for each separation component.
 * 2. Notice buyout and arrears are ALWAYS fully taxable (salary income).
 * 3. Sum taxable portions of all components.
 * 4. Compute annual taxable: salary YTD + taxable separation − deductions.
 * 5. Compute annual tax via existing `computeTax()`.
 * 6. TDS on separation = annual tax − TDS already deducted this FY.
 * 7. Net payable = total gross − TDS on separation.
 */
export function computeFnfSettlement(input: FnfInput): FnfResult {
  // Step 1: Exemptions
  const gratuityExemption = computeGratuityExemption({
    actualGratuityMinor: input.gratuityGrossMinor,
    lastDrawnWagesMinor: input.lastDrawnWagesMinor,
    completedYears: input.completedYears,
    employeeCategory: input.employeeCategory,
    ceilingMinor: input.gratuityCeilingMinor,
  });

  const leaveEncashExemption = computeLeaveEncashExemption({
    actualEncashmentMinor: input.leaveEncashmentGrossMinor,
    avgSalaryLast10MonthsMinor: input.avgSalaryLast10MonthsMinor,
    leaveBalanceDays: input.leaveBalanceDays,
    completedYears: input.completedYears,
    employeeCategory: input.employeeCategory,
    separationType: input.separationType,
    ceilingMinor: input.leaveEncashCeilingMinor,
    priorExemptionClaimedMinor: input.priorLeaveEncashExemptionMinor,
  });

  const retrenchmentExemption = computeRetrenchmentExemption({
    actualCompMinor: input.retrenchmentCompMinor,
    avgMonthlyPayMinor: input.lastDrawnWagesMinor,
    completedYears: input.completedYears,
    separationType: input.separationType,
    ceilingMinor: input.retrenchmentCeilingMinor,
  });

  const vrsExemption = computeVrsExemption({
    actualCompMinor: input.vrsCompMinor,
    monthlySalaryMinor: input.lastDrawnWagesMinor,
    completedYears: input.completedYears,
    remainingMonthsToRetirement: input.remainingMonthsToRetirement,
    separationType: input.separationType,
    ceilingMinor: input.vrsCeilingMinor,
  });

  // Step 2: Total gross
  const totalGrossMinor =
    input.noticeBuyoutMinor +
    input.leaveEncashmentGrossMinor +
    input.gratuityGrossMinor +
    input.retrenchmentCompMinor +
    input.vrsCompMinor +
    input.arrearsMinor;

  // Step 3: Total exempt
  const totalExemptMinor =
    gratuityExemption.exemptMinor +
    leaveEncashExemption.exemptMinor +
    (retrenchmentExemption?.exemptMinor ?? 0n) +
    (vrsExemption?.exemptMinor ?? 0n);

  // Step 4: Total taxable on separation
  // Notice buyout and arrears are fully taxable (salary income u/s 17(1))
  const totalTaxableOnSeparationMinor =
    input.noticeBuyoutMinor +
    input.arrearsMinor +
    gratuityExemption.taxableMinor +
    leaveEncashExemption.taxableMinor +
    (retrenchmentExemption?.taxableMinor ?? 0n) +
    (vrsExemption?.taxableMinor ?? 0n);

  // Step 5: Annual taxable income for the FY
  const totalSalaryIncomeMinor = input.salaryYtdMinor + totalTaxableOnSeparationMinor;
  const stdDed = BigInt(stdDeduction(input.taxRegime, input.fyStartYear)) * 100n; // convert rupees to paise
  const chapterViA = input.taxRegime === "old"
    ? input.deductions80cMinor + input.deductions80dMinor + input.otherDeductionsMinor
    : 0n; // New regime: no Ch VI-A deductions

  let annualTaxableMinor = totalSalaryIncomeMinor - stdDed - chapterViA;
  if (annualTaxableMinor < 0n) annualTaxableMinor = 0n;

  // Step 6: Compute annual tax (convert paise to rupees for the engine, then back)
  const taxableRupees = Math.round(Math.max(0, Number(annualTaxableMinor) / 100) / 10) * 10; // Sec 288A rounding
  const taxResult = computeTax(taxableRupees, input.taxRegime, input.fyStartYear);
  const annualTaxMinor = BigInt(taxResult.totalTax) * 100n;

  // Step 7: TDS on separation = annual tax − YTD TDS
  let tdsOnSeparationMinor = annualTaxMinor - input.tdsYtdMinor;
  if (tdsOnSeparationMinor < 0n) tdsOnSeparationMinor = 0n;

  // Step 8: Net payable = total gross − TDS deducted on F&F
  const netPayableMinor = totalGrossMinor - tdsOnSeparationMinor;

  return {
    gratuityExemption,
    leaveEncashExemption,
    retrenchmentExemption,
    vrsExemption,
    totalGrossMinor,
    totalExemptMinor,
    totalTaxableOnSeparationMinor,
    annualTaxableMinor,
    annualTaxMinor,
    tdsAlreadyDeductedMinor: input.tdsYtdMinor,
    tdsOnSeparationMinor,
    netPayableMinor,
  };
}

services/payroll-service/src/modules/pay.source:
import { hraExemptionMinor, annualTaxFromTaxableMinor, trueUpTdsMinor, type Regime } from "../tax/engine.js";

/** Employee tax declaration inputs for old-regime exemptions (annual paise). */
export interface TaxDeclarationInput {
  rentPaidAnnualMinor?: bigint;
  ded80cMinor?: bigint;
  ded80dMinor?: bigint;
  otherDedMinor?: bigint;
  /** Previous-employer taxable salary for this FY (Sec 192(2), both regimes). */
  prevEmployerSalaryMinor?: bigint;
  /** Income reported under "income from other sources" (both regimes). */
  otherSourcesIncomeMinor?: bigint;
  /** Perquisites value, Sec 17(2) — added to salary income (both regimes). */
  perquisitesMinor?: bigint;
}

export class DomainError extends Error {
  constructor(public code: string, message: string) {
    super(`[${code}] ${message}`);
    this.name = "DomainError";
  }
}

export interface PayComponent {
  code: string;
  name: string;
  type: "earning" | "deduction";
  amountMinor: bigint;
}

/** Raw structure component as configured (fixed amount OR percentage of basic). */
export interface RawComponent {
  code: string;
  name: string;
  type: "earning" | "deduction";
  fixedMinor?: bigint | null;
  pctOfBasic?: number | null; // e.g. 10 => 10% of basic
}

export type PensionScheme = "GPF" | "NPS" | "EPF";
export type CityClass = "X" | "Y" | "Z";

export interface SlipInput {
  basicMinor: bigint;
  /** Dearness Allowance rate in basis points (e.g. 5000 = 50.00%). */
  daRateBps?: bigint;
  /** HRA city classification (X=metro 24/27/30, Y=16/18/20, Z=8/9/10). */
  cityClass?: CityClass;
  /** Monthly Professional Tax to deduct (already capped to FY 2500 limit upstream). */
  ptMinor?: bigint;
  /** Extra ad-hoc components (LOP, loan EMI, arrears, reimbursements). */
  components?: PayComponent[];
  /** Structure components evaluated for fixed/pct (DA & HRA handled specially). */
  rawComponents?: RawComponent[];
  pensionScheme?: PensionScheme;
  /** Income-tax regime + FY start year for monthly TDS (defaults: new / 2025). */
  taxRegime?: Regime;
  fyStartYear?: number;
  /** Old-regime declaration (HRA rent, 80C, 80D, other Chapter VI-A). */
  declaration?: TaxDeclarationInput;
  /** Sec 192 true-up: TDS already deducted YTD this FY + months left (incl. this one). */
  tdsYtdMinor?: bigint;
  monthsRemaining?: number;
  /**
   * P3: protected-net floor (paise). Recovery deductions (LOP, loan EMI, arrears
   * recovery) are capped so net pay never drops below this floor; the uncapped
   * remainder is reported as `recoveryCarryForwardMinor` to be recovered later.
   */
  protectedNetFloorMinor?: bigint;
  /** Sec 10(5) LTC exemption total for this employee in the current FY (paise). */
  ltcExemptTotalMinor?: bigint;
}

/** Deduction codes treated as "recovery" — subject to the protected-net floor. */
const RECOVERY_CODES = new Set(["LOP", "LOAN_EMI", "ARREAR_RECOVERY"]);

export interface SlipResult {
  grossMinor: bigint;
  totalDeductionsMinor: bigint;
  netPayMinor: bigint;
  daMinor: bigint;
  hraMinor: bigint;
  earnings: PayComponent[];
  deductions: PayComponent[];
  pfEmployeeMinor: bigint;
  pfEmployerMinor: bigint;   // total employer 12%
  epsMinor: bigint;          // employer EPS portion (8.33%, capped 1250)
  epfEmployerMinor: bigint;  // employer EPF portion (12% total - EPS)
  esiMinor: bigint;
  esiEmployerMinor: bigint;
  ptMinor: bigint;
  tdsMinor: bigint;
  gpfMinor: bigint;
  npsEmployeeMinor: bigint;
  npsEmployerMinor: bigint;
  annualTaxableMinor: bigint;
  negativeNet: boolean;
  /** P3: recovery (LOP/EMI/arrears) deferred because it would breach the net floor. */
  recoveryCarryForwardMinor: bigint;
}

const PF_PCT      = 12n;
const PF_WAGE_CAP = 1_500_000n;  // EPF/EPS wage ceiling: 15000 INR
const EPS_CAP     = 125_000n;    // EPS max: 1250 INR (8.33% of 15000)
const ESI_CAP     = 2_100_000n;  // ESI gross ceiling: 21000 INR
const GPF_PCT     = 10n;
const NPS_EMP_PCT = 10n;
const NPS_ER_PCT  = 14n;
const GRATUITY_CAP = 200_000_000n; // 20 lakh INR

/** Round a paise amount to the nearest whole rupee (round-half-up). */
export function roundRupee(x: bigint): bigint {
  if (x < 0n) return -roundRupee(-x);
  return ((x + 50n) / 100n) * 100n;
}

function pct(base: bigint, percent: bigint): bigint {
  return roundRupee((base * percent) / 100n);
}

/** 7th CPC HRA slab % by city class, escalating with DA threshold (50% / 100%). */
export function hraSlabPct(cityClass: CityClass, daRateBps: bigint): bigint {
  const tier = daRateBps >= 10000n ? 2 : daRateBps >= 5000n ? 1 : 0; // DA>=100% / >=50%
  const table: Record<CityClass, [bigint, bigint, bigint]> = {
    X: [24n, 27n, 30n],
    Y: [16n, 18n, 20n],
    Z: [8n, 9n, 10n],
  };
  return table[cityClass][tier];
}

export function computeSlip(input: SlipInput): SlipResult {
  const {
    basicMinor,
    daRateBps = 0n,
    cityClass = "X",
    ptMinor = 0n,
    components = [],
    rawComponents = [],
    pensionScheme = "EPF",
    taxRegime = "new",
    fyStartYear = 2025,
    declaration = {},
    tdsYtdMinor,
    monthsRemaining,
    protectedNetFloorMinor = 0n,
    ltcExemptTotalMinor = 0n,
  } = input;

  const earnings: PayComponent[] = [];
  const deductions: PayComponent[] = [];

  // Basic is the first earning.
  earnings.push({ code: "BASIC", name: "Basic Pay", type: "earning", amountMinor: basicMinor });

  // Dearness Allowance = DA% of basic.
  const daMinor = roundRupee((basicMinor * daRateBps) / 10000n);
  if (daMinor > 0n) earnings.push({ code: "DA", name: "Dearness Allowance", type: "earning", amountMinor: daMinor });

  // HRA = city-class slab % of basic (escalates with DA threshold).
  const hraMinor = pct(basicMinor, hraSlabPct(cityClass, daRateBps));
  if (hraMinor > 0n) earnings.push({ code: "HRA", name: "House Rent Allowance", type: "earning", amountMinor: hraMinor });

  // Evaluate remaining structure components (skip BASIC/DA/HRA — handled above).
  for (const c of rawComponents) {
    if (["BASIC", "DA", "HRA"].includes(c.code)) continue;
    const amt = c.pctOfBasic != null && c.pctOfBasic > 0
      ? pct(basicMinor, BigInt(Math.round(c.pctOfBasic)))
      : roundRupee(c.fixedMinor ?? 0n);
    if (amt === 0n) continue;
    (c.type === "earning" ? earnings : deductions).push({ code: c.code, name: c.name, type: c.type, amountMinor: amt });
  }

  // Ad-hoc components (LOP, EMI, arrears, reimbursements).
  for (const c of components) {
    (c.type === "earning" ? earnings : deductions).push({ ...c, amountMinor: roundRupee(c.amountMinor) });
  }

  const grossMinor = earnings.reduce((s, e) => s + e.amountMinor, 0n);

  // Pension contributions are computed on Basic + DA.
  const pensionBase = basicMinor + daMinor;

  let pfEmployeeMinor = 0n, pfEmployerMinor = 0n, epsMinor = 0n, epfEmployerMinor = 0n;
  let gpfMinor = 0n, npsEmployeeMinor = 0n, npsEmployerMinor = 0n;

  if (pensionScheme === "GPF") {
    gpfMinor = pct(pensionBase, GPF_PCT);
  } else if (pensionScheme === "NPS") {
    npsEmployeeMinor = pct(pensionBase, NPS_EMP_PCT);
    npsEmployerMinor = pct(pensionBase, NPS_ER_PCT);
  } else {
    const pfWage    = pensionBase > PF_WAGE_CAP ? PF_WAGE_CAP : pensionBase;
    pfEmployeeMinor = pct(pfWage, PF_PCT);
    pfEmployerMinor = pct(pfWage, PF_PCT);
    const epsWage   = pensionBase > PF_WAGE_CAP ? PF_WAGE_CAP : pensionBase;
    epsMinor        = roundRupee((epsWage * 833n) / 10000n);
    if (epsMinor > EPS_CAP) epsMinor = EPS_CAP;
    epfEmployerMinor = pfEmployerMinor - epsMinor;
  }

  const esiMinor         = grossMinor <= ESI_CAP ? roundRupee((grossMinor * 75n) / 10000n) : 0n;
  const esiEmployerMinor = grossMinor <= ESI_CAP ? roundRupee((grossMinor * 325n) / 10000n) : 0n;

  const pt = roundRupee(ptMinor);
  if (pt > 0n) deductions.push({ code: "PT", name: "Professional Tax", type: "deduction", amountMinor: pt });

  // Monthly TDS (Sec 192) on real annual TAXABLE income: regime-aware, with
  // Sec 16 std deduction + PT, Sec 10(13A) HRA exemption, and Chapter VI-A (old regime).
  const annualGross = grossMinor * 12n;
  // Additions taxed under BOTH regimes (added before slabs):
  //  - perquisites Sec 17(2) (current employer, not part of cash gross),
  //  - previous-employer taxable salary for the FY (Sec 192(2)),
  //  - income from other sources.
  const perqMinor       = declaration.perquisitesMinor ?? 0n;
  const prevEmpSalMinor = declaration.prevEmployerSalaryMinor ?? 0n;
  const otherSrcMinor   = declaration.otherSourcesIncomeMinor ?? 0n;
  const extraIncome     = perqMinor + prevEmpSalMinor + otherSrcMinor;
  let annualTaxableMinor: bigint;
  if (taxRegime === "old") {
    const salaryHraAnnual   = (basicMinor + daMinor) * 12n;
    const hraReceivedAnnual = hraMinor * 12n;
    const rentAnnual        = declaration.rentPaidAnnualMinor ?? 0n;
    const hraExempt = hraExemptionMinor(salaryHraAnnual, hraReceivedAnnual, rentAnnual, cityClass === "X");
    const d80c = declaration.ded80cMinor ?? 0n; const c80c = d80c > 15_000_000n ? 15_000_000n : d80c;
    const d80d = declaration.ded80dMinor ?? 0n; const c80d = d80d > 7_500_000n ? 7_500_000n : d80d;
    const other = declaration.otherDedMinor ?? 0n;
    annualTaxableMinor = annualGross + extraIncome - 5_000_000n - hraExempt - c80c - c80d - other - pt * 12n - ltcExemptTotalMinor;
  } else {
    annualTaxableMinor = annualGross + extraIncome - 7_500_000n - ltcExemptTotalMinor; // new regime: standard deduction + LTC exempt
  }
  if (annualTaxableMinor < 0n) annualTaxableMinor = 0n;
  const annualTaxMinor = annualTaxFromTaxableMinor(annualTaxableMinor, taxRegime, fyStartYear);
  const tdsMinor = monthsRemaining != null
    ? trueUpTdsMinor(annualTaxMinor, tdsYtdMinor ?? 0n, monthsRemaining)         // Sec 192 true-up
    : (annualTaxMinor / 100n / 12n) * 100n;                                       // flat /12 fallback

  // Statutory pension/insurance/tax deductions are never floored.
  const statutoryDeductions = pfEmployeeMinor + esiMinor + tdsMinor + gpfMinor + npsEmployeeMinor;

  // Split ad-hoc deductions into recovery (floor-capped) and fixed (e.g. PT, and
  // any structure-defined deduction). Fixed deductions are not subject to the floor.
  const recoveryRequested = deductions
    .filter((d) => RECOVERY_CODES.has(d.code))
    .reduce((s, d) => s + d.amountMinor, 0n);
  const fixedAdHoc = deductions
    .filter((d) => !RECOVERY_CODES.has(d.code))
    .reduce((s, d) => s + d.amountMinor, 0n);

  // Headroom available for recovery after gross less all non-recovery deductions,
  // keeping net at or above the protected floor.
  const nonRecovery   = statutoryDeductions + fixedAdHoc;
  const headroom      = grossMinor - nonRecovery - protectedNetFloorMinor;
  const recoveryCap   = headroom < 0n ? 0n : headroom;
  const recoveryApplied = recoveryRequested > recoveryCap ? recoveryCap : recoveryRequested;
  const recoveryCarryForwardMinor = recoveryRequested - recoveryApplied;

  // If recovery was capped, scale down the recovery deduction line items so the
  // persisted slip reflects what was actually withheld (carry the remainder).
  if (recoveryCarryForwardMinor > 0n && recoveryRequested > 0n) {
    let remainingToTrim = recoveryCarryForwardMinor;
    // Trim from the largest recovery lines first (deterministic by amount desc).
    const recoveryLines = deductions
      .filter((d) => RECOVERY_CODES.has(d.code))
      .sort((a, b) => (a.amountMinor < b.amountMinor ? 1 : -1));
    for (const line of recoveryLines) {
      if (remainingToTrim <= 0n) break;
      const trim = line.amountMinor < remainingToTrim ? line.amountMinor : remainingToTrim;
      line.amountMinor -= trim;
      remainingToTrim -= trim;
    }
    // Drop fully-trimmed recovery lines.
    for (let i = deductions.length - 1; i >= 0; i--) {
      const d = deductions[i]!;
      if (RECOVERY_CODES.has(d.code) && d.amountMinor === 0n) deductions.splice(i, 1);
    }
  }

  const totalDeductions = nonRecovery + recoveryApplied;
  const netRaw          = grossMinor - totalDeductions;
  // With the floor enforced, netRaw can still legitimately be 0 (no floor + full
  // recovery). negativeNet now only ever true if floor is 0 and fixed/statutory
  // alone exceed gross (an upstream data error worth flagging as an exception).
  const negativeNet     = netRaw < 0n;

  return {
    grossMinor,
    totalDeductionsMinor: totalDeductions,
    netPayMinor: negativeNet ? 0n : netRaw,
    recoveryCarryForwardMinor,
    daMinor, hraMinor, earnings, deductions,
    pfEmployeeMinor, pfEmployerMinor, epsMinor, epfEmployerMinor,
    esiMinor, esiEmployerMinor, ptMinor: pt, tdsMinor,
    gpfMinor, npsEmployeeMinor, npsEmployerMinor, annualTaxableMinor, negativeNet,
  };
}

// ============================ Pensioner payroll ============================

/**
 * CCS (Pension) additional-pension (quantum of pension) age bands. From the age
 * the pensioner attains in the run month, an extra % of basic pension is paid:
 *   80–84: 20%, 85–89: 30%, 90–94: 40%, 95–99: 50%, 100+: 100%.
 */
export function additionalPensionPct(ageYears: number): bigint {
  if (ageYears >= 100) return 100n;
  if (ageYears >= 95)  return 50n;
  if (ageYears >= 90)  return 40n;
  if (ageYears >= 85)  return 30n;
  if (ageYears >= 80)  return 20n;
  return 0n;
}

/** Whole years attained on/before the last day of the run month (YYYY-MM). */
export function ageAtMonth(dobIso: string, month: string): number {
  const dob = new Date(`${dobIso.slice(0, 10)}T00:00:00Z`);
  const [y, m] = month.split("-").map(Number) as [number, number];
  // Reference = last day of run month.
  const ref = new Date(Date.UTC(y, m, 0));
  let age = ref.getUTCFullYear() - dob.getUTCFullYear();
  const mo = ref.getUTCMonth() - dob.getUTCMonth();
  if (mo < 0 || (mo === 0 && ref.getUTCDate() < dob.getUTCDate())) age -= 1;
  return age < 0 ? 0 : age;
}

export interface PensionInput {
  basicPensionMinor: bigint;
  /** Dearness Relief rate in basis points (same series as DA, e.g. 5000 = 50%). */
  drRateBps?: bigint;
  /** Portion of basic pension that was commuted (deducted until restoration). */
  commutedPensionMinor?: bigint;
  /** Commutation date — commuted portion is restored 15 years after it. */
  commutationDate?: string | null;
  /** Fixed monthly medical allowance (paise). */
  medicalAllowanceMinor?: bigint;
  /** Pensioner date of birth (drives additional-pension age band). */
  dateOfBirth: string;
  /** Run month YYYY-MM. */
  month: string;
  /** Monthly TDS on pension (pension is taxable as salary). 0 if none. */
  tdsMinor?: bigint;
}

export interface PensionResult {
  grossMinor: bigint;
  totalDeductionsMinor: bigint;
  netPayMinor: bigint;
  basicPensionMinor: bigint;
  /** Net basic pension actually disbursed (basic less un-restored commutation). */
  payableBasicPensionMinor: bigint;
  drMinor: bigint;
  additionalPensionMinor: bigint;
  additionalPensionPct: bigint;
  medicalAllowanceMinor: bigint;
  commutationDeductionMinor: bigint;
  commutationRestored: boolean;
  tdsMinor: bigint;
  ageYears: number;
  earnings: PayComponent[];
  deductions: PayComponent[];
}

/**
 * Monthly pension computation (distinct from the salary slip):
 *   gross = basic pension + additional pension (age band % of basic)
 *           + DR on (basic + additional) + fixed medical allowance.
 * The commuted portion is withheld from basic until it is restored 15 years
 * after the commutation date (CCS rule), after which the full basic is paid.
 * DR (Dearness Relief) is computed on basic + additional pension.
 */
export function computePension(input: PensionInput): PensionResult {
  const {
    basicPensionMinor,
    drRateBps = 0n,
    commutedPensionMinor = 0n,
    commutationDate = null,
    medicalAllowanceMinor = 0n,
    dateOfBirth,
    month,
    tdsMinor = 0n,
  } = input;

  const ageYears = ageAtMonth(dateOfBirth, month);
  const addlPct = additionalPensionPct(ageYears);
  const additionalPensionMinor = pct(basicPensionMinor, addlPct);

  // Restoration: 15 years after commutation date the commuted portion is restored.
  let commutationRestored = true;
  if (commutedPensionMinor > 0n && commutationDate) {
    const cd = new Date(`${commutationDate.slice(0, 10)}T00:00:00Z`);
    const restoreOn = new Date(Date.UTC(cd.getUTCFullYear() + 15, cd.getUTCMonth(), cd.getUTCDate()));
    const [y, m] = month.split("-").map(Number) as [number, number];
    const runEnd = new Date(Date.UTC(y, m, 0));
    commutationRestored = runEnd >= restoreOn;
  } else if (commutedPensionMinor > 0n) {
    // Commuted but no date provided — treat as not yet restored.
    commutationRestored = false;
  }
  const commutationDeductionMinor = commutationRestored ? 0n : commutedPensionMinor;
  const payableBasicPensionMinor = basicPensionMinor - commutationDeductionMinor;

  // DR is on basic + additional pension (full basic, not reduced by commutation).
  const drBase = basicPensionMinor + additionalPensionMinor;
  const drMinor = roundRupee((drBase * drRateBps) / 10000n);
  const medical = roundRupee(medicalAllowanceMinor);

  const earnings: PayComponent[] = [];
  earnings.push({ code: "BASIC_PENSION", name: "Basic Pension", type: "earning", amountMinor: basicPensionMinor });
  if (additionalPensionMinor > 0n)
    earnings.push({ code: "ADDL_PENSION", name: `Additional Pension (${addlPct}%)`, type: "earning", amountMinor: additionalPensionMinor });
  if (drMinor > 0n)
    earnings.push({ code: "DR", name: "Dearness Relief", type: "earning", amountMinor: drMinor });
  if (medical > 0n)
    earnings.push({ code: "FMA", name: "Medical Allowance", type: "earning", amountMinor: medical });

  // Gross is the full entitlement; commutation withholding and TDS are deductions.
  const grossMinor = basicPensionMinor + additionalPensionMinor + drMinor + medical;

  const deductions: PayComponent[] = [];
  if (commutationDeductionMinor > 0n)
    deductions.push({ code: "COMMUTATION", name: "Commuted Pension", type: "deduction", amountMinor: commutationDeductionMinor });
  const tds = roundRupee(tdsMinor);
  if (tds > 0n)
    deductions.push({ code: "TDS", name: "Income Tax (TDS)", type: "deduction", amountMinor: tds });

  const totalDeductionsMinor = commutationDeductionMinor + tds;
  const netPayMinor = grossMinor - totalDeductionsMinor;

  return {
    grossMinor, totalDeductionsMinor, netPayMinor,
    basicPensionMinor, payableBasicPensionMinor,
    drMinor, additionalPensionMinor, additionalPensionPct: addlPct,
    medicalAllowanceMinor: medical,
    commutationDeductionMinor, commutationRestored,
    tdsMinor: tds, ageYears, earnings, deductions,
  };
}

export function assertRunStatusTransition(current: string, next: string): void {
  const allowed: Record<string, string[]> = {
    draft:      ["processing"],
    processing: ["approved", "failed"],
    approved:   ["disbursed"],
    disbursed:  [],
    failed:     ["draft"],
  };
  if (!(allowed[current] ?? []).includes(next)) {
    throw new DomainError("INVALID_STATUS_TRANSITION", `cannot move payroll run from '${current}' to '${next}'`);
  }
}

/**
 * Payment of Gratuity Act / CCS: (15/26) * (last Basic+DA) * completed years,
 * where >=6 months in the final year rounds up; capped at 20 lakh.
 */
export function computeGratuity(yearsOfService: number, lastBasicMinor: bigint, lastDaMinor = 0n): bigint {
  if (yearsOfService < 5) return 0n;
  const whole = Math.floor(yearsOfService);
  const fracMonths = Math.round((yearsOfService - whole) * 12);
  const completedYears = BigInt(whole + (fracMonths >= 6 ? 1 : 0));
  const emoluments = lastBasicMinor + lastDaMinor;
  const raw = (emoluments * 15n * completedYears) / 26n;
  const rounded = roundRupee(raw);
  return rounded > GRATUITY_CAP ? GRATUITY_CAP : rounded;
}

services/workflow-service/src/modules/au.source:
/**
 * CAP-025 — Delegation-of-power + monetary authority matrix (pure domain).
 *
 * Resolves the financial/administrative authority available to an actor from a
 * set of effective-dated limits, decides whether a requested amount is within
 * that authority, and — when it is exceeded — walks the escalation chain to the
 * lowest office whose limit covers the amount (the approver the case must route
 * to). All functions are pure: no I/O, no clock; the caller supplies `onDate`.
 */

export type AuthorityScope = "role" | "designation" | "user";
export type AuthorityType = "financial" | "administrative";

export interface AuthorityLimit {
  id: string;
  scopeType: AuthorityScope;
  scopeRef: string;
  authorityType: AuthorityType;
  currency: string;
  /** Inclusive maximum amount the scope may authorise. */
  maxAmount: number;
  /** YYYY-MM-DD (inclusive). */
  effectiveFrom: string;
  /** YYYY-MM-DD (inclusive) or null = open-ended. */
  effectiveTo: string | null;
  /** Where a request exceeding this limit escalates to (null = terminal). */
  escalateToScopeType: AuthorityScope | null;
  escalateToRef: string | null;
  /** Only 'active' limits are considered by resolution. */
  status: string;
}

/** An actor's identity for authority resolution: their roles/designations/self. */
export interface ActorScopes {
  scopes: Array<{ scopeType: AuthorityScope; scopeRef: string }>;
}

export interface AuthorityDecision {
  /** The best (highest) limit the actor personally holds, or null if none. */
  actorLimit: AuthorityLimit | null;
  /** The actor's ceiling (0 when the actor holds no applicable limit). */
  actorMax: number;
  /** True when `amount` is within the actor's own authority. */
  withinActorAuthority: boolean;
  /** True when the amount exceeds the actor and must route upward. */
  requiresEscalation: boolean;
  /** Ordered chain of offices the request escalates through (excludes actor). */
  escalationChain: Array<{ scopeType: AuthorityScope; scopeRef: string; maxAmount: number }>;
  /** The final office whose limit covers the amount, or null if uncovered. */
  finalApprover: { scopeType: AuthorityScope; scopeRef: string; maxAmount: number } | null;
  /** True when SOME office in the chain covers the amount. */
  covered: boolean;
}

/** A limit is effective on `onDate` when active and the date is within bounds. */
export function isEffective(limit: AuthorityLimit, onDate: string): boolean {
  if (limit.status !== "active") return false;
  if (limit.effectiveFrom > onDate) return false;
  if (limit.effectiveTo !== null && limit.effectiveTo < onDate) return false;
  return true;
}

/** Effective limits matching an exact scope + authority type on a date. */
export function limitsForScope(
  limits: AuthorityLimit[],
  scopeType: AuthorityScope,
  scopeRef: string,
  authorityType: AuthorityType,
  onDate: string,
): AuthorityLimit[] {
  return limits.filter(
    (l) =>
      l.scopeType === scopeType &&
      l.scopeRef === scopeRef &&
      l.authorityType === authorityType &&
      isEffective(l, onDate),
  );
}

/** Highest-authority effective limit for a single scope (or null). */
export function bestLimitForScope(
  limits: AuthorityLimit[],
  scopeType: AuthorityScope,
  scopeRef: string,
  authorityType: AuthorityType,
  onDate: string,
): AuthorityLimit | null {
  const matches = limitsForScope(limits, scopeType, scopeRef, authorityType, onDate);
  if (matches.length === 0) return null;
  return matches.reduce((best, l) => (l.maxAmount > best.maxAmount ? l : best));
}

/**
 * The actor's own authority: across ALL their scopes (roles/designations/self),
 * the single effective limit with the greatest ceiling. Returns null when the
 * actor holds no applicable limit.
 */
export function resolveActorLimit(
  limits: AuthorityLimit[],
  actor: ActorScopes,
  authorityType: AuthorityType,
  onDate: string,
): AuthorityLimit | null {
  let best: AuthorityLimit | null = null;
  for (const s of actor.scopes) {
    const l = bestLimitForScope(limits, s.scopeType, s.scopeRef, authorityType, onDate);
    if (l && (best === null || l.maxAmount > best.maxAmount)) best = l;
  }
  return best;
}

/**
 * Walk the escalation chain upward from `start` until an office's limit covers
 * `amount`, the chain terminates, or a cycle is detected. The returned chain
 * lists each office visited (in order); `finalApprover` is the covering office
 * (or null). Guarded against cycles by tracking visited limit ids.
 */
export function resolveEscalation(
  limits: AuthorityLimit[],
  start: AuthorityLimit,
  amount: number,
  authorityType: AuthorityType,
  onDate: string,
): Pick<AuthorityDecision, "escalationChain" | "finalApprover" | "covered"> {
  const chain: AuthorityDecision["escalationChain"] = [];
  const visited = new Set<string>([start.id]);
  let cursor: AuthorityLimit | null = start;

  while (cursor && cursor.escalateToScopeType && cursor.escalateToRef) {
    const next: AuthorityLimit | null = bestLimitForScope(
      limits,
      cursor.escalateToScopeType,
      cursor.escalateToRef,
      authorityType,
      onDate,
    );
    if (!next || visited.has(next.id)) break; // dead end or cycle
    visited.add(next.id);
    const node = { scopeType: next.scopeType, scopeRef: next.scopeRef, maxAmount: next.maxAmount };
    chain.push(node);
    if (amount <= next.maxAmount) {
      return { escalationChain: chain, finalApprover: node, covered: true };
    }
    cursor = next;
  }
  return { escalationChain: chain, finalApprover: null, covered: false };
}

/**
 * Full authority evaluation for a request of `amount` by an actor on `onDate`.
 * If the actor's own limit covers the amount, no escalation is required; else
 * the escalation chain is resolved from the actor's best limit (or, when the
 * actor holds no limit at all, from the highest applicable limit of any scope
 * they hold — falling through to whatever escalation targets exist).
 */
export function evaluateAuthority(
  limits: AuthorityLimit[],
  actor: ActorScopes,
  authorityType: AuthorityType,
  amount: number,
  onDate: string,
): AuthorityDecision {
  const actorLimit = resolveActorLimit(limits, actor, authorityType, onDate);
  const actorMax = actorLimit?.maxAmount ?? 0;
  const withinActorAuthority = actorLimit !== null && amount <= actorMax;

  if (withinActorAuthority) {
    return {
      actorLimit,
      actorMax,
      withinActorAuthority: true,
      requiresEscalation: false,
      escalationChain: [],
      finalApprover: actorLimit
        ? { scopeType: actorLimit.scopeType, scopeRef: actorLimit.scopeRef, maxAmount: actorLimit.maxAmount }
        : null,
      covered: true,
    };
  }

  // Exceeds (or actor holds no limit): escalate from the actor's best limit.
  const esc = actorLimit
    ? resolveEscalation(limits, actorLimit, amount, authorityType, onDate)
    : { escalationChain: [], finalApprover: null, covered: false };

  return {
    actorLimit,
    actorMax,
    withinActorAuthority: false,
    requiresEscalation: true,
    escalationChain: esc.escalationChain,
    finalApprover: esc.finalApprover,
    covered: esc.covered,
  };
}

services/workflow-service/src/modules/qu.source:
/**
 * CAP-026 — Parallel / conditional / quorum approvals (pure domain).
 *
 * Two independent, side-effect-free primitives:
 *  - tallyQuorum: committee/board decision over a fixed membership under one of
 *    three rules (majority / unanimous / threshold), returning an EARLY decision
 *    the moment the outcome is mathematically settled (so a board need not wait
 *    for stragglers once approval is unreachable or already secured).
 *  - consolidateParallel: fold the outcomes of parallel workflow branches into
 *    a single result under an all-must or any policy.
 */

export type QuorumRule = "majority" | "unanimous" | "threshold";
export type VoteChoice = "approve" | "reject" | "abstain";
export type Outcome = "approve" | "reject";

export interface QuorumInput {
  rule: QuorumRule;
  /** Total eligible members of the committee. */
  totalMembers: number;
  /** Approvals required — only for rule='threshold'. */
  threshold?: number | null;
  votes: VoteChoice[];
}

export interface QuorumTally {
  approvals: number;
  rejections: number;
  abstentions: number;
  /** Non-null votes cast (approve|reject|abstain). */
  cast: number;
  /** Members who have not yet voted. */
  pending: number;
  decided: boolean;
  outcome: Outcome | null;
  rationale: string;
}

/**
 * Tally a committee decision. A decision is returned as soon as it is settled:
 *  - majority: approve once approvals exceed half the membership; reject once
 *    approval is unreachable (approvals + still-pending can no longer exceed
 *    half) or rejections already exceed half.
 *  - unanimous: approve only when EVERY member voted approve; reject the instant
 *    any member rejects, or once all have voted and unanimity was not reached
 *    (an abstention breaks unanimity).
 *  - threshold(N): approve once approvals reach N; reject once N is unreachable.
 */
export function tallyQuorum(input: QuorumInput): QuorumTally {
  const total = Math.max(0, Math.trunc(input.totalMembers));
  let approvals = 0;
  let rejections = 0;
  let abstentions = 0;
  for (const v of input.votes) {
    if (v === "approve") approvals++;
    else if (v === "reject") rejections++;
    else abstentions++;
  }
  const cast = approvals + rejections + abstentions;
  const pending = Math.max(0, total - cast);
  const base: Omit<QuorumTally, "decided" | "outcome" | "rationale"> = {
    approvals,
    rejections,
    abstentions,
    cast,
    pending,
  };

  const settle = (outcome: Outcome | null, rationale: string): QuorumTally => ({
    ...base,
    decided: outcome !== null,
    outcome,
    rationale,
  });

  if (total <= 0) return settle(null, "no eligible members");

  switch (input.rule) {
    case "majority": {
      const half = total / 2;
      if (approvals > half) return settle("approve", `majority reached (${approvals}/${total})`);
      if (rejections > half) return settle("reject", `majority rejected (${rejections}/${total})`);
      // approval unreachable even if every pending member approves
      if (approvals + pending <= half) {
        return settle("reject", `approval unreachable (max ${approvals + pending}/${total})`);
      }
      return settle(null, `pending (${approvals} approve / ${rejections} reject / ${pending} awaited)`);
    }
    case "unanimous": {
      if (rejections > 0) return settle("reject", "unanimity broken by a rejection");
      if (approvals === total) return settle("approve", `unanimous (${approvals}/${total})`);
      if (pending === 0) return settle("reject", "all voted but not unanimous (abstention present)");
      return settle(null, `pending unanimity (${approvals}/${total}, ${pending} awaited)`);
    }
    case "threshold": {
      const need = Math.max(1, Math.trunc(input.threshold ?? 0));
      if (approvals >= need) return settle("approve", `threshold met (${approvals}/${need})`);
      if (approvals + pending < need) {
        return settle("reject", `threshold unreachable (max ${approvals + pending}/${need})`);
      }
      return settle(null, `pending threshold (${approvals}/${need}, ${pending} awaited)`);
    }
  }
}

export type BranchOutcome = "approve" | "reject" | "pending";
export type ParallelMode = "all" | "any";

export interface ParallelResult {
  outcome: BranchOutcome;
  approvals: number;
  rejections: number;
  pending: number;
  rationale: string;
}

/**
 * Consolidate parallel branch outcomes.
 *  - all (all-must): approve only when every branch approved; reject the instant
 *    any branch rejected; otherwise pending.
 *  - any (any-one): approve the instant any branch approved; reject only when
 *    every branch rejected; otherwise pending.
 */
export function consolidateParallel(mode: ParallelMode, branches: BranchOutcome[]): ParallelResult {
  const approvals = branches.filter((b) => b === "approve").length;
  const rejections = branches.filter((b) => b === "reject").length;
  const pending = branches.filter((b) => b === "pending").length;
  const n = branches.length;
  const base = { approvals, rejections, pending };

  if (n === 0) return { ...base, outcome: "pending", rationale: "no branches" };

  if (mode === "all") {
    if (rejections > 0) return { ...base, outcome: "reject", rationale: "a required branch rejected" };
    if (approvals === n) return { ...base, outcome: "approve", rationale: "all branches approved" };
    return { ...base, outcome: "pending", rationale: `${approvals}/${n} branches approved` };
  }
  // any
  if (approvals > 0) return { ...base, outcome: "approve", rationale: "a branch approved" };
  if (rejections === n) return { ...base, outcome: "reject", rationale: "all branches rejected" };
  return { ...base, outcome: "pending", rationale: `awaiting a branch approval (${rejections}/${n} rejected)` };
}

services/finance-service/src/modules/bud.source:
/** Pure budget domain logic — no DB, no HTTP, no queue. Unit-tested in isolation. */

export class DomainError extends Error {
  constructor(public code: string, message: string) {
    super(`[${code}] ${message}`);
    this.name = "DomainError";
  }
}

export type SanctionStatus = "draft" | "approved" | "exhausted" | "cancelled";

export interface BudgetAvailability {
  reMinor: bigint;
  utilisedMinor: bigint;
}

/** Returns available balance (re_minor - utilised_minor). */
export function availableBalance(b: BudgetAvailability): bigint {
  return b.reMinor - b.utilisedMinor;
}

/** Throws if bill amount exceeds available budget. */
export function assertBudgetNotExceeded(available: bigint, requested: bigint): void {
  if (requested > available) {
    throw new DomainError(
      "BUDGET_EXCEEDED",
      `requested ${requested} paise exceeds available ${available} paise`
    );
  }
}

export interface SanctionAvailability {
  amountMinor: bigint;
  utilisedMinor: bigint;
}

/** Remaining unspent balance on a sanction. */
export function sanctionAvailable(s: SanctionAvailability): bigint {
  return s.amountMinor - s.utilisedMinor;
}

export function assertSanctionNotExhausted(s: SanctionAvailability, requested: bigint): void {
  const avail = sanctionAvailable(s);
  if (requested > avail) {
    throw new DomainError(
      "SANCTION_EXHAUSTED",
      `requested ${requested} paise exceeds sanction balance ${avail} paise`
    );
  }
}

/** FY must be in YYYY-YY format, e.g. 2024-25. */
export function assertValidFY(fy: string): void {
  if (!/^\d{4}-\d{2}$/.test(fy)) {
    throw new DomainError("INVALID_FY", `fiscal year must be YYYY-YY, got '${fy}'`);
  }
}

/**
 * GFR Rule 11: Revised Estimate (reMinor) cannot exceed Budget Estimate (beMinor).
 * Release orders must be backed by sanctioned budget — prevents over-release.
 */
export function assertReleaseWithinSanction(beMinor: bigint, newReMinor: bigint): void {
  if (newReMinor > beMinor) {
    throw new DomainError(
      "GFR_RULE_11_VIOLATION",
      `revised estimate ${newReMinor} paise exceeds budget estimate ${beMinor} paise (GFR Rule 11)`
    );
  }
}

/**
 * GFR Rule 10 — re-appropriation is a ZERO-SUM transfer: an amount withdrawn
 * from a source head's savings is added to a target head. It must be met from
 * the source head's *savings* (its unspent revised estimate), and total
 * appropriation is conserved. The receiving head's RE may legitimately exceed
 * its own BE — that is the entire purpose of re-appropriation — so the Rule-11
 * RE≤BE cap must NOT be applied to the target here.
 */
export interface ReappropriationSource {
  reMinor: bigint;       // source head revised estimate
  utilisedMinor: bigint; // already spent/committed on the source head
}
export function assertReappropriationValid(source: ReappropriationSource, amountMinor: bigint): void {
  if (amountMinor <= 0n) {
    throw new DomainError("INVALID_AMOUNT", "re-appropriation amount must be positive");
  }
  const savings = source.reMinor - source.utilisedMinor;
  if (amountMinor > savings) {
    throw new DomainError(
      "INSUFFICIENT_SAVINGS",
      `re-appropriation ${amountMinor} paise exceeds source head savings ${savings} paise (GFR Rule 10: must be met from savings)`
    );
  }
}

/**
 * R11 — maker-checker separation of duties. A sanction must be approved by an
 * officer other than the one who raised it. Self-approval (single-officer
 * sanction) is rejected so a financial commitment always has two distinct
 * accountable parties (GFR maker-checker; DFPR delegation).
 */
export function assertSanctionApproverDistinct(createdBy: string, approverId: string): void {
  if (createdBy === approverId) {
    throw new DomainError(
      "MAKER_CHECKER_VIOLATION",
      "sanction approver must differ from the officer who created it (maker-checker)"
    );
  }
}

export { assertValidPfmsHoA, assertValidDdoCode } from "../../shared/pfms.js";

